import React from 'react';
import type { Meta, StoryObj } from "@storybook/nextjs";
import { ArrowForward, OpenInNew, Download } from "../../icons";
import { Box, Flex, Text } from "../index";

import { Link, LinkStory } from "./Link";

const meta: Meta<typeof LinkStory> = {
  title: "Design System/Atoms/Link",
  component: LinkStory,
  parameters: {
    docs: {
      description: {
        component: `A styled Next.js Link component for navigation within the application and to external resources. Built on Next.js Link with support for client-side routing, SVG icons, and multiple visual variants.

**Accessibility:**
- Keyboard navigation: Links are fully keyboard accessible with Tab and Enter
- For external links, add \`target="_blank"\` and \`rel="noopener noreferrer"\` for security
- Consider adding \`aria-label\` for icon-only links or when link text needs clarification
- Use OpenInNew icon to visually indicate external links
- Screen readers announce links as "link" role automatically

**Best practices:**
- Use descriptive link text (avoid "click here" or "read more")
- For external links, include OpenInNew icon and open in new tab
- For downloads, include Download icon
- For navigation arrows, use ArrowForward icon
- Set \`disabled\` prop instead of removing href to maintain keyboard focus order`,
      },
    },
  },
  argTypes: {
    children: {
      control: 'text',
      description: 'Link content (text, icons, or mixed content)',
      table: {
        type: { summary: 'ReactNode' },
      },
    },
    href: {
      control: 'text',
      description: 'Destination URL or path',
      table: {
        type: { summary: 'string' },
      },
    },
    variant: {
      control: { type: 'select' },
      options: ['default', 'docs'],
      description: 'Link visual style variant',
      table: {
        type: { summary: '"default" | "docs"' },
        defaultValue: { summary: 'default' },
      },
    },
    disabled: {
      control: 'boolean',
      description: 'Disables link interaction and applies muted styling',
      table: {
        type: { summary: 'boolean' },
        defaultValue: { summary: 'false' },
      },
    },
    target: {
      control: { type: 'select' },
      options: [undefined, '_blank', '_self', '_parent', '_top'],
      description: 'Where to open the link (use _blank for external links)',
      table: {
        type: { summary: 'string' },
      },
    },
    rel: {
      control: 'text',
      description: 'Relationship attribute (use "noopener noreferrer" with target="_blank")',
      table: {
        type: { summary: 'string' },
      },
    },
  },
};

export default meta;
